import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
function trans(key, params) {
  return app.translator.trans(`forumcopilot-flapp.forum.authorize.${key}`, params);
}

/**
 * /flapp/authorize: where a member lets an app sign in through this forum, in
 * the phone's browser. A guest logs in or signs up first, with the forum's own
 * modals; both reload the page, which then asks to Authorize. The forum has
 * already checked the request (AuthorizeContent) and named the app.
 */
export default class AuthorizePage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.request = app.data.flappAuthorize || {
      error: true
    };
    this.params = new URLSearchParams(window.location.search);
    this.working = false;
    this.done = false;
    app.setTitle(trans('title', {
      app: this.request.appName || 'Flapp'
    }));
  }
  view() {
    return m("div", {
      className: "FlappAuthorizePage"
    }, m("div", {
      className: "container",
      style: {
        maxWidth: '480px',
        paddingTop: '40px',
        paddingBottom: '40px'
      }
    }, this.content()));
  }
  content() {
    const request = this.request;
    if (request.error) return m("p", null, trans('invalid_text'));
    if (this.done) return m("p", null, trans('done_text', {
      app: request.appName
    }));
    const user = app.session.user;
    const forum = app.forum.attribute('title');
    if (!user) {
      return [m("h2", null, trans('guest_heading', {
        app: request.appName
      })), m("p", null, trans('guest_text', {
        app: request.appName,
        forum
      })), m("div", {
        className: "Form-group"
      }, m(Button, {
        className: "Button Button--primary Button--block",
        onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
      }, app.translator.trans('core.forum.header.log_in_link'))), app.forum.attribute('allowSignUp') ? m("div", {
        className: "Form-group"
      }, m(Button, {
        className: "Button Button--block",
        onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/SignUpModal'))
      }, app.translator.trans('core.forum.header.sign_up_link'))) : null, m("p", null, m("a", {
        href: request.cancelUrl
      }, trans('cancel_button')))];
    }
    return [m("h2", null, trans('member_heading', {
      app: request.appName,
      forum,
      username: user.username()
    })), m("p", null, trans('member_text', {
      app: request.appName
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      loading: this.working,
      disabled: this.working,
      onclick: this.authorize.bind(this)
    }, trans('authorize_button'))), m("div", {
      className: "Form-group"
    }, m("a", {
      className: "Button Button--block",
      href: request.cancelUrl
    }, trans('cancel_button'))), m("p", null, m("a", {
      href: "#",
      onclick: this.logOut.bind(this)
    }, trans('not_you_link', {
      username: user.username()
    })))];
  }
  authorize() {
    this.working = true;

    // A failure shows Flarum's own alert.
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/flapp-auth/approve',
      body: {
        app: this.params.get('app'),
        publicKey: this.params.get('publicKey'),
        nonce: this.params.get('nonce')
      }
    }).then(result => {
      this.done = true;
      window.location.href = result.redirect;
    }).finally(() => {
      this.working = false;
      m.redraw();
    });
  }

  // Signed in as someone else in this browser: log out and come back here.
  // Flarum 2.0 logs out with a POST.
  logOut(e) {
    e.preventDefault();
    const form = document.createElement('form');
    form.method = 'POST';
    form.action = `${app.forum.attribute('baseUrl')}/logout?return=${encodeURIComponent(window.location.href)}`;
    const token = document.createElement('input');
    token.type = 'hidden';
    token.name = 'csrfToken';
    token.value = app.session.csrfToken;
    form.appendChild(token);
    document.body.appendChild(form);
    form.submit();
  }
}
flarum.reg.add('forumcopilot-flapp', 'forum/components/AuthorizePage', AuthorizePage);